export const QUTTY_MCP_SCRIPT =
  '#!/usr/bin/env bash\n# qutty-mcp: the Qutty agent hub\'s MCP server, as a stdio command. It relays MCP\'s JSON-RPC lines\n# to this tile\'s hub socket ($QUTTY_SOCK, set by Qutty in every tile); the socket tells the hub\n# which tile is talking. Outside Qutty it exits at once, so a user-scope registration is harmless\n# in other terminals. Installed to ~/.qutty/bin by Qutty (updated on every start).\n[ -n "${QUTTY_SOCK:-}" ] && [ -S "$QUTTY_SOCK" ] || exit 0\n# BSD/OpenBSD netcat has -U (unix sockets); busybox nc does not, so fall back to socat.\nif command -v nc >/dev/null 2>&1 && nc -h 2>&1 | grep -q -- \'-U\'; then\n  exec nc -U "$QUTTY_SOCK"\nfi\nif command -v socat >/dev/null 2>&1; then\n  exec socat - "UNIX-CONNECT:$QUTTY_SOCK"\nfi\necho "qutty-mcp: needs nc with -U (BSD netcat) or socat" >&2\nexit 1\n';

